<script setup lang="ts">
import { computed, ref, watch,onMounted,onUnmounted } from 'vue'
import NavMenu from './NavMenu.vue'
import { useRoute } from 'vue-router'
import { api,lang,language,t,translated,menuTree,sectionName,type Organization,type Content,type List,type MenuItem,type Upload } from '../api'
const location=window.location
const route=useRoute();const site=ref<{central:boolean;domain:string;organization?:Organization;menu:MenuItem[]}>();const list=ref<Content[]>([]);const catalog=ref<Organization[]>([]);const detail=ref<Content>();const loading=ref(true);const error=ref('');const q=ref('');const kind=ref('');const page=ref(1);const total=ref(0);let revision=0
const section=computed(()=>route.path.split('/')[1]||'home');const org=computed(()=>site.value?.organization);const nav=computed(()=>site.value?.menu.filter(item=>item.visible)||[])
const navigation=ref<HTMLElement>()
const schoolCover=ref<Upload>()
const banners=ref<{file:Upload;title:Record<string,{title:string;body:string}>}[]>([]);const bannerIndex=ref(0)
const activeBanner=computed(()=>banners.value[bannerIndex.value])
function changeBanner(step:number){bannerIndex.value=(bannerIndex.value+step+banners.value.length)%banners.value.length}
const staffPage=computed(()=>['administration','teachers'].includes(section.value))
const tree=computed(()=>menuTree(site.value?.menu||[]))
const accessibleKeys=computed(()=>{const keys=new Set<string>();const walk=(nodes:ReturnType<typeof menuTree>)=>{for(const item of nodes){keys.add(item.key);walk(item.children)}};walk(tree.value);return keys})
function closeMenus(){navigation.value?.querySelectorAll('details[open]').forEach(el=>el.removeAttribute('open'))}
function outside(event:MouseEvent){if(!navigation.value?.contains(event.target as Node))closeMenus()}
function escape(event:KeyboardEvent){if(event.key==='Escape'){const summary=(document.activeElement as HTMLElement)?.closest('details')?.querySelector('summary');closeMenus();summary?.focus()}}
onMounted(()=>{document.addEventListener('click',outside);document.addEventListener('keydown',escape)})
onUnmounted(()=>{document.removeEventListener('click',outside);document.removeEventListener('keydown',escape)})
watch(()=>route.path,closeMenus)
const menuTitle=computed(()=>nav.value.find(item=>item.key===section.value)?.label[lang.value])
function excerpt(c:Content){const el=document.createElement('div');el.innerHTML=c.translations[lang.value]?.body||'';el.querySelectorAll('a').forEach(a=>a.remove());return el.textContent?.trim()||''}
function cover(c:Content){return c.files.find(f=>f.mime.startsWith('image/'))}

const title=computed(()=>section.value==='home'?t('Білім. Балалар. Болашақ.','Образование. Дети. Будущее.'):section.value==='catalog'?t('Ұйымдар каталогы','Каталог организаций'):menuTitle.value||sectionName(section.value))
async function load(){const rev=++revision;loading.value=true;error.value='';detail.value=undefined;try{schoolCover.value=undefined;banners.value=[];bannerIndex.value=0;const current=await api('/site');if(rev!==revision)return;site.value=current;if(section.value==='catalog'&&current.central){const data=await api<List<Organization>>(`/catalog?q=${encodeURIComponent(q.value)}&kind=${kind.value}&page=${page.value}`);if(rev!==revision)return;catalog.value=data.items;total.value=data.total}else if(section.value!=='contacts'){const allowed=section.value==='home'||accessibleKeys.value.has(section.value);if(!allowed)throw new Error(t('Бет табылмады','Страница не найдена'));const id=route.path.split('/')[2];if(id){const data=await api<Content>('/content/'+encodeURIComponent(id));if(rev!==revision)return;detail.value=data}else{if(section.value==='home'&&current.organization){const slides:Content[]=[];let bannerPage=1;let result:List<Content>;do{result=await api<List<Content>>('/content?kind=banners&page='+bannerPage++);if(rev!==revision)return;slides.push(...result.items)}while(slides.length<result.total&&result.items.length);banners.value=slides.flatMap(c=>c.files.filter(f=>f.mime.startsWith('image/')).map(file=>({file,title:c.translations})));const about=await api<List<Content>>('/content?kind=about');if(rev!==revision)return;schoolCover.value=about.items[0]?.files.find(file=>file.mime.startsWith('image/'))}const data=await api<List<Content>>(`/content?kind=${section.value==='home'?'news':section.value}&page=${page.value}`);if(rev!==revision)return;list.value=data.items;total.value=data.total}}}catch(e){if(rev===revision)error.value=(e as Error).message}finally{if(rev===revision)loading.value=false}}
function search(){page.value=1;load()}
watch(()=>route.path,()=>{page.value=1;load()},{immediate:true});watch(page,load)
function url(o:Organization){return `${location.protocol}//${o.slug}.${site.value?.domain}${location.port?':'+location.port:''}`}
</script>
<template>
<div class="public-shell"><header class="site-header"><RouterLink to="/" class="brand"><img class="brand-mark" src="/shymkent-logo.svg" width="56" height="56" :alt="t('Шымкент қаласының логотипі','Логотип города Шымкент')"><span>{{ org?translated(org.name):t('ШЫМКЕНТ · БІЛІМ','ШЫМКЕНТ · ОБРАЗОВАНИЕ') }}<small>{{ t('Шымкент қаласының мектептері мен балабақшалары','Школы и детские сады города Шымкент') }}</small></span></RouterLink><div class="languages" aria-label="Language"><button :aria-pressed="lang==='kk'" @click="language('kk')">ҚАЗ</button><button :aria-pressed="lang==='ru'" @click="language('ru')">РУС</button></div><RouterLink v-if="site" to="/admin/" class="quiet">{{t('Кіру','Войти')}}</RouterLink></header>
<nav ref="navigation" class="public-nav" :aria-label="t('Негізгі навигация','Основная навигация')"><div class="nav-inner"><NavMenu :items="tree" :active-key="section" /></div></nav>
<main><p v-if="org?.slug.startsWith('demo-')" class="demo-banner">{{t('Демонстрациялық мектеп · мәліметтер мен оқиғалар ойдан шығарылған','Демонстрационная школа · сведения и события вымышлены')}}</p><section class="hero" :class="{compact:section!=='home'}"><div><p class="eyebrow">{{org?t('ШЫМКЕНТ · БІЛІМ БЕРУ ҰЙЫМЫ','ШЫМКЕНТ · ОБРАЗОВАТЕЛЬНАЯ ОРГАНИЗАЦИЯ'):t('ШЫМКЕНТ ҚАЛАСЫ · БІРЫҢҒАЙ ПОРТАЛ','ГОРОД ШЫМКЕНТ · ЕДИНЫЙ ПОРТАЛ')}}</p><h1>{{section==='home'&&org?translated(org.name):title}}</h1><p v-if="section==='home'">{{org?org.profile['summary_'+lang]:t('Туған қаламыздың болашағын бірге құрамыз. Шымкент мектептері мен балабақшаларының жаңалықтары, құжаттары және байланыстары бір жерде.','Вместе создаём будущее родного города. Новости, документы и контакты школ и детских садов Шымкента в одном месте.')}}</p><RouterLink v-if="site?.central&&section==='home'" to="/catalog" class="button">{{t('Ұйымды табу','Найти организацию')}} <span>↗</span></RouterLink></div><figure v-if="section==='home'&&org&&activeBanner" class="hero-photo"><img :src="'/files/'+activeBanner.file.id" :width="activeBanner.file.width" :height="activeBanner.file.height" :alt="activeBanner.file.caption[lang]||activeBanner.title[lang]?.title" fetchpriority="high"><figcaption><span>{{activeBanner.file.caption[lang]||activeBanner.title[lang]?.title}}</span><div v-if="banners.length>1" class="banner-controls"><button type="button" @click="changeBanner(-1)" :aria-label="t('Алдыңғы баннер','Предыдущий баннер')">←</button><span aria-live="polite">{{bannerIndex+1}} / {{banners.length}}</span><button type="button" @click="changeBanner(1)" :aria-label="t('Келесі баннер','Следующий баннер')">→</button></div></figcaption></figure><figure v-else-if="section==='home'&&org&&schoolCover" class="hero-photo"><img :src="'/files/'+schoolCover.id" :width="schoolCover.width" :height="schoolCover.height" :alt="t('Мектеп кеңістігінің иллюстрациялық фотосы','Иллюстративная фотография школьного пространства')" fetchpriority="high"><figcaption><span>{{t('Оқу кеңістігі','Пространство для учёбы')}}</span><a href="https://unsplash.com" target="_blank" rel="noopener noreferrer">{{t('Unsplash · иллюстрациялық фото ↗','Unsplash · иллюстративное фото ↗')}}</a></figcaption></figure><img v-else-if="org?.profile.logo&&section!=='home'&&!org.slug.startsWith('demo-')" :src="'/files/'+org.profile.logo+'?thumbnail=1'" width="140" height="140" :alt="translated(org.name)" class="logo"><figure v-else-if="section==='home'&&!org" class="hero-photo"><img src="/school-life.jpg" width="1200" height="900" :alt="t('Шымкенттің №59 мектебіндегі Білім күні','День знаний в школе №59 Шымкента')" fetchpriority="high"><figcaption><span>{{t('Мектеп өмірі · Шымкент','Школьная жизнь · Шымкент')}}</span><a href="https://59-shymkent.edu.kz/main/533-1-yrkjek-blm-kn.html" target="_blank" rel="noopener noreferrer">{{t('№59 мектеп · дереккөз ↗','Школа №59 · источник ↗')}}</a></figcaption></figure></section>
<div v-if="section==='home'&&org" class="quick-links"><RouterLink v-if="accessibleKeys.has('about')" to="/about"><span class="quick-icon">⌂</span><div><strong>{{t('Мектеп туралы','О школе')}}</strong><small>{{t('Оқу кеңістігі және жобалар','Учебное пространство и проекты')}}</small></div><span>↗</span></RouterLink><RouterLink v-if="accessibleKeys.has('teachers')" to="/teachers"><span class="quick-icon">♧</span><div><strong>{{t('Біздің педагогтер','Наши педагоги')}}</strong><small>{{t('Мектеп ұжымымен танысыңыз','Познакомьтесь с коллективом')}}</small></div><span>↗</span></RouterLink><RouterLink v-if="accessibleKeys.has('schedule')" to="/schedule"><span class="quick-icon">▤</span><div><strong>{{t('Сабақ кестесі','Расписание занятий')}}</strong><small>{{t('Оқу аптасының PDF үлгісі','PDF с учебной неделей')}}</small></div><span>↗</span></RouterLink></div><div v-if="section==='home'&&site?.central" class="quick-links"><RouterLink to="/catalog"><span class="quick-icon">⌂</span><div><strong>{{t('Мектептер мен балабақшалар','Школы и детские сады')}}</strong><small>{{t('Ұйымның сайтын және байланысын табыңыз','Найдите сайт и контакты организации')}}</small></div><span>↗</span></RouterLink><RouterLink to="/documents"><span class="quick-icon">▤</span><div><strong>{{t('Құжаттар','Документы')}}</strong><small>{{t('Қажетті ақпарат бір жерде','Нужная информация в одном месте')}}</small></div><span>↗</span></RouterLink><RouterLink to="/news"><span class="quick-icon">☷</span><div><strong>{{t('Білім жаңалықтары','Новости образования')}}</strong><small>{{t('Қаланың мектеп өмірі','Школьная жизнь города')}}</small></div><span>↗</span></RouterLink></div><div v-if="error" class="notice" role="alert">{{error}} <button @click="load">{{t('Қайталау','Повторить')}}</button></div><p v-else-if="loading" role="status" class="empty">{{t('Жүктелуде…','Загрузка…')}}</p>
<template v-else>
<section v-if="section==='catalog'"><form class="filters" @submit.prevent="search"><label>{{t('Атауы немесе нөмірі','Название или номер')}}<input v-model="q" :placeholder="t('Мысалы, 51','Например, 51')"></label><label>{{t('Ұйым түрі','Тип организации')}}<select v-model="kind"><option value="">{{t('Барлығы','Все')}}</option><option value="school">{{t('Мектеп','Школа')}}</option><option value="preschool">{{t('Балабақша','Дошкольная организация')}}</option></select></label><button class="button">{{t('Іздеу','Найти')}}</button></form><p class="eyebrow">{{total}} {{t('ҰЙЫМ','ОРГАНИЗАЦИЙ')}}</p><div class="cards"><a v-for="o in catalog" :key="o.id" :href="url(o)" class="org-card"><span class="tag">{{o.kind==='school'?t('Мектеп','Школа'):t('Балабақша','Дошкольная организация')}}</span><h2>{{translated(o.name)}}</h2><p>{{o.profile['address_'+lang]}}</p><span class="card-link">{{t('Сайтқа өту','Открыть сайт')}} ↗</span></a></div><p v-if="!catalog.length" class="empty">{{t('Ұйымдар табылмады','Организации не найдены')}}</p></section>
<section v-else-if="section==='contacts'&&org" class="contact-card"><h2>{{t('Байланыс деректері','Контактная информация')}}</h2><p>{{org.profile['address_'+lang]||t('Мекенжай қосылмаған','Адрес не добавлен')}}</p><p>{{org.profile.phone}}</p><a v-if="org.profile.email" :href="'mailto:'+org.profile.email">{{org.profile.email}}</a><p><a v-if="org.profile.map_url" :href="org.profile.map_url" target="_blank" rel="noopener noreferrer">{{t('Картада ашу','Открыть на карте')}} ↗</a></p></section>
<section v-else><div class="section-heading"><h2 v-if="section==='home'">{{t('Соңғы жаңалықтар','Последние новости')}}</h2><span class="eyebrow">{{detail?'':total+' '+t('МАТЕРИАЛ','МАТЕРИАЛОВ')}}</span></div><div :class="detail?'':['content-grid',{'staff-grid':staffPage,'wide-content':['about','schedule'].includes(section),'album-grid':section==='gallery'}]"><article v-for="c in detail?[detail]:list" :key="c.id" class="content-card" :class="{'news-card':!detail&&c.kind==='news','staff-card':staffPage}"><RouterLink v-if="!detail&&c.kind==='news'&&cover(c)" :to="'/news/'+c.id" class="news-cover" tabindex="-1" aria-hidden="true"><img :src="'/files/'+cover(c)!.id+'?thumbnail=1'" :width="cover(c)!.width" :height="cover(c)!.height" alt="" loading="lazy"></RouterLink><div v-else-if="!detail&&c.kind==='news'" class="news-cover news-cover-text"><span>ШЫМКЕНТ · БІЛІМ</span><strong>{{t('Мектеп өмірі','Школьная жизнь')}}</strong></div><div v-if="staffPage&&cover(c)" class="staff-cover"><img :src="'/files/'+cover(c)!.id+'?thumbnail=1'" :width="cover(c)!.width" :height="cover(c)!.height" :alt="t('Педагогтің иллюстрациялық портреті','Иллюстративный портрет сотрудника')" loading="lazy"></div><div class="content-body"><p v-if="!staffPage" class="eyebrow">{{new Date(c.kind==='schedule'&&c.schedule_date?c.schedule_date+'T00:00:00':c.updated_at).toLocaleDateString(lang==='kk'?'kk-KZ':'ru-RU')}}</p><h2><RouterLink v-if="!detail&&c.kind==='news'" :to="'/news/'+c.id">{{c.translations[lang]?.title||t('Аударма әлі қосылмаған','Перевод ещё не добавлен')}}</RouterLink><template v-else>{{c.translations[lang]?.title||t('Аударма әлі қосылмаған','Перевод ещё не добавлен')}}</template></h2><p v-if="!detail&&c.kind==='news'" class="news-excerpt">{{excerpt(c)}}</p><div v-else-if="c.translations[lang]?.title" class="prose" v-html="c.translations[lang].body"></div><RouterLink v-if="!detail&&c.kind==='news'" :to="'/news/'+c.id" class="card-link">{{t('Толығырақ','Читать подробнее')}} →</RouterLink><div v-if="!staffPage&&(detail||c.kind!=='news')" :class="c.kind==='gallery'?'gallery':'attachments'"><figure v-for="f in c.files" :key="f.id"><a v-if="f.mime.startsWith('image/')" :href="'/files/'+f.id" target="_blank" rel="noopener"><img :src="'/files/'+f.id+'?thumbnail=1'" :width="f.width||720" :height="f.height||480" loading="lazy" :alt="f.caption[lang]||f.name"></a><a v-else :href="'/files/'+f.id" target="_blank" rel="noopener">{{f.name}} ↗</a><figcaption>{{f.caption[lang]}}</figcaption><a :href="'/files/'+f.id+'?download=1'" class="quiet">{{t('Жүктеу','Скачать')}}</a></figure></div></div></article></div><p v-if="!detail&&!list.length" class="empty">{{t('Материалдар әлі жарияланбаған','Материалы ещё не опубликованы')}}</p></section>
<div v-if="!detail&&total>20" class="pagination"><button :disabled="page===1" @click="page--">← {{t('Алдыңғы','Назад')}}</button><span>{{page}} / {{Math.ceil(total/20)}}</span><button :disabled="page*20>=total" @click="page++">{{t('Келесі','Далее')}} →</button></div>
</template></main><footer><span>ШЫМКЕНТ · {{t('Шымкенттің білім кеңістігі','Образование Шымкента')}}</span><a v-if="site&&!site.central" :href="`${location.protocol}//${site.domain}${location.port?':'+location.port:''}`">{{t('Орталық портал','Центральный портал')}} ↗</a><span>{{new Date().getFullYear()}}</span></footer></div>
</template>
